public class Main {
    public static void main(String[] args) {
        // Array: ukuran tetap, ditentukan saat dibuat
        int[] arr = new int[3];
        arr[0] = 10;
        System.out.println(arr.length + " " + Arrays.toString(arr));

        // ArrayList: ukurannya mengikuti isi
        List<Integer> list = new ArrayList<>();
        list.add(10);
        list.add(20);
        list.add(0, 5);                    // sisip di depan
        list.remove(Integer.valueOf(20));  // hapus nilai 20
        System.out.println(list.size() + " " + list);
        System.out.println(list.get(1) + " " + list.contains(10));

        // List.of: daftar tetap yang tidak boleh diubah
        List<String> hari = List.of("Senin", "Selasa");
        System.out.println(hari + " berisi " + hari.size() + " hari");
    }
}

