import java.util.*;

public class Main {
    static boolean seimbang(String s) {
        Stack<Character> st = new Stack<>();
        for (char c : s.toCharArray()) {
            if ("([{".indexOf(c) >= 0) {
                st.push(c);
            } else if (")]}".indexOf(c) >= 0) {
                if (st.isEmpty() || "([{".indexOf(st.pop()) != ")]}".indexOf(c)) {
                    return false;
                }
            }
        }
        return st.isEmpty();
    }

    public static void main(String[] args) {
        String[] rumus = {"(a+b)*[c-d]", "{[(])}", "((x)"};
        for (String s : rumus) {
            System.out.println(s + " -> " + seimbang(s));
        }
    }
}

