        stok.put(barang, sisa - jumlah);
        System.out.println("Ambil " + jumlah + " " + barang + ", sisa " + (sisa - jumlah));
    }

    public static void main(String[] args) {
        Map<String, Integer> stok = new HashMap<>();
        stok.put("beras 5 kg", 3);
        try {
            ambil(stok, "beras 5 kg", 2);
            ambil(stok, "beras 5 kg", 4);
        } catch (StokHabisException e) {
