public class Main {
    static int cariBiner(int[] a, int target) {
        int kiri = 0, kanan = a.length - 1;
        while (kiri <= kanan) {
            int tengah = (kiri + kanan) / 2;
            if (a[tengah] == target) {
                return tengah;
            } else if (a[tengah] < target) {
                kiri = tengah + 1;
            } else {
                kanan = tengah - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] harga = {2000, 3500, 5000, 7500, 10000, 12000, 15000, 20000};
