public class Main {
    static class ListNode {
        int data;
        ListNode next;
        ListNode(int data, ListNode next) {
            this.data = data;
            this.next = next;
        }
    }

    static class LinkedIntList {
        private ListNode front;

        void addFirst(int nilai) {
            front = new ListNode(nilai, front);
        }

        void addLast(int nilai) {
            if (front == null) {
                front = new ListNode(nilai, null);
            } else {
                ListNode cur = front;
                while (cur.next != null) {
                    cur = cur.next;
                }
                cur.next = new ListNode(nilai, null);
            }
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (ListNode cur = front; cur != null; cur = cur.next) {
                sb.append(cur.data).append(" -> ");
            }
            return sb.append("null").toString();
        }
    }

    public static void main(String[] args) {
        LinkedIntList list = new LinkedIntList();
        list.addLast(20);
        list.addLast(30);
        list.addFirst(10);
        System.out.println(list);
    }
}

