public class Main {
    public static void main(String[] args) throws FileNotFoundException {
        File f = new File("nilai.txt");
        PrintWriter tulis = new PrintWriter(f);
        tulis.println("Budi 85 90");
        tulis.println("Sari 80 90");
        tulis.close();

        Scanner baca = new Scanner(f);
        while (baca.hasNextLine()) {
            String baris = baca.nextLine();
            Scanner token = new Scanner(baris);
            String nama = token.next();
            int total = 0, n = 0;
