import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;

public class Main {
    static String sha256(String data) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(data.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    public static void main(String[] args) {
        String asli = "installer-v1.2";
        String unduhan = "installer-v1.2";
        String rusak = "installer-v1.3";
        System.out.println("Hash asli  : " + sha256(asli).substring(0, 16) + "...");
        System.out.println("Unduhan cocok? " + sha256(asli).equals(sha256(unduhan)));
        System.out.println("File rusak cocok? " + sha256(asli).equals(sha256(rusak)));
    }
}

