public class Main {
    static class Diskon {
        static long hitung(long harga, int persen) {
            if (persen < 0 || persen > 100) throw new IllegalArgumentException("persen salah");
            return harga - harga * persen / 100;
        }
    }

    static void cek(String nama, long harapan, long hasil) {
        System.out.println((harapan == hasil ? "LULUS " : "GAGAL ") + nama + ": harapan " + harapan + ", hasil " + hasil);
    }

    public static void main(String[] args) {
        cek("diskon 10%", 45_000, Diskon.hitung(50_000, 10));
        cek("tanpa diskon", 80_000, Diskon.hitung(80_000, 0));
        cek("diskon penuh", 0, Diskon.hitung(80_000, 100));
        try {
            Diskon.hitung(1000, -5);
            System.out.println("GAGAL persen negatif: tidak ditolak");
        } catch (IllegalArgumentException e) {
            System.out.println("LULUS persen negatif ditolak");
        }
    }
}

