public class Main {
    /**
     * Kalkulator ongkos kirim kurir reguler.
     *
     * <p>Berat dibulatkan ke atas per 1 kg.
     */
    static class Ongkir {
        /** Tarif per kilogram dalam rupiah. */
        static final int TARIF_PER_KG = 9000;

        /**
         * Menghitung ongkos kirim.
         *
         * @param beratGram berat paket dalam gram, harus lebih dari 0
         * @return ongkos kirim dalam rupiah
         * @throws IllegalArgumentException jika {@code beratGram <= 0}
         */
        static int hitung(int beratGram) {
            if (beratGram <= 0) {
                throw new IllegalArgumentException("berat harus > 0");
            }
            int kg = (beratGram + 999) / 1000;
            return kg * TARIF_PER_KG;
        }
    }

    public static void main(String[] args) {
        System.out.println(Ongkir.hitung(1500));
        System.out.println(Ongkir.hitung(3000));
    }
}

