     * @param saldo   saldo dalam rupiah, tidak negatif
     */
    record Rekening(String nomor, String pemilik, long saldo) {}

    public static void main(String[] args) {
        Rekening r = new Rekening("1234567890", "Siti Rahma", 2_500_000);
        System.out.println(r.pemilik() + " saldo " + r.saldo());
    }
}

public class Main {
    static class Harga {
        /** Tarif PPN dalam persen. */
        static final int PPN = 11;

        /**
         * Menambahkan PPN ke harga dasar.
         *
         * <p>Besarnya mengikuti {@link #PPN}. Untuk harga setelah diskon,
         * hitung diskonnya dulu baru panggil method ini.
         *
         * @param hargaDasar harga sebelum pajak
         * @return harga setelah PPN
         * @see <a href="https://pajak.go.id">Informasi PPN</a>
         */
        static long setelahPpn(long hargaDasar) {
            return hargaDasar + hargaDasar * PPN / 100;
        }
    }

    public static void main(String[] args) {
        System.out.println(Harga.setelahPpn(100_000));
    }
}

