public class Main {
    static int cekBalik(int n) {
        int b = 0;
        while (n > 0) {
            b = b * 10 + n % 10;
            n /= 10;
        }
        return b;
    }

    public static void main(String[] args) {
        int angka = 120345;
        int sisa = angka, balik = 0;
        while (sisa > 0) {
            balik = balik * 10 + sisa % 10;
            sisa /= 10;
        }
        System.out.println(angka + " dibalik menjadi " + balik);
        System.out.println("12321 palindrom angka? " + (cekBalik(12321) == 12321));
    }
}

public class Main {
    public static void main(String[] args) {
        String kalimat = "Kasur ini rusak";
        String bersih = kalimat.replace(" ", "").toLowerCase();
        int kiri = 0, kanan = bersih.length() - 1;
        boolean palindrom = true;
        while (kiri < kanan) {
            if (bersih.charAt(kiri) != bersih.charAt(kanan)) {
                palindrom = false;
                break;
            }
            kiri++;
            kanan--;
        }
        System.out.println("\"" + kalimat + "\" palindrom? " + palindrom);
    }
}

public class Main {
    public static void main(String[] args) {
        int[] harga = {5000, 8000, 12000, 15000, 20000, 27000, 35000};
        int cari = 9000;
        int kiri = 0, kanan = harga.length - 1, langkah = 0;
        boolean ketemu = false;
        while (kiri <= kanan) {
            langkah++;
            int tengah = (kiri + kanan) / 2;
            if (harga[tengah] == cari) {
                ketemu = true;
                break;
            } else if (harga[tengah] < cari) {
                kiri = tengah + 1;
            } else {
                kanan = tengah - 1;
            }
        }
        System.out.println(cari + " ketemu? " + ketemu + " (" + langkah + " langkah, berhenti saat kiri=" + kiri + " > kanan=" + kanan + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        String[] tamu = {"Adit", "Bela", "Doni", "Fitri", "Hana", "Indra", "Joni", "Kirana"};
        String cari = "Indra";
        int kiri = 0, kanan = tamu.length - 1, posisi = -1;
        while (kiri <= kanan) {
            int tengah = (kiri + kanan) / 2;
            int banding = tamu[tengah].compareTo(cari);
            if (banding == 0) {
                posisi = tengah;
                break;
            } else if (banding < 0) {
                kiri = tengah + 1;
            } else {
                kanan = tengah - 1;
            }
        }
        System.out.println(cari + " ada di nomor urut " + (posisi + 1));
    }
}

public class Main {
    public static void main(String[] args) {
        int[] kursi = new int[1000];
        for (int i = 0; i < kursi.length; i++) {
            kursi[i] = i + 1;
        }
        int[] dicari = {1, 500, 999};
        for (int cari : dicari) {
            int kiri = 0, kanan = kursi.length - 1, langkah = 0;
            while (kiri <= kanan) {
                langkah++;
                int tengah = (kiri + kanan) / 2;
                if (kursi[tengah] == cari) break;
                else if (kursi[tengah] < cari) kiri = tengah + 1;
                else kanan = tengah - 1;
            }
            System.out.println("Kursi " + cari + ": " + langkah + " langkah");
        }
    }
